            <style>
            .inventory-drop{display:flex;min-height:118px;align-items:center;justify-content:center;padding:18px;border:2px dashed #cbd5e1;border-radius:12px;background:rgba(248,250,252,.7);text-align:center;cursor:pointer}.inventory-drop.dragging{border-color:#6366f1;background:rgba(99,102,241,.08)}.inventory-drop strong{display:block;margin-bottom:7px;color:#334155}.inventory-drop small{color:#64748b}.inventory-buttons{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}.inventory-summary{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0}.inventory-summary span{padding:5px 9px;border-radius:999px;background:#eef2ff;color:#4338ca;font-size:13px}.inventory-toolbar{display:flex;align-items:end;justify-content:space-between;gap:12px;margin-bottom:12px}.inventory-toolbar label{flex:1;max-width:360px}.inventory-toolbar input{width:100%;margin-top:6px}.inventory-table-wrap{max-height:520px;overflow:auto;border:1px solid #e2e8f0;border-radius:10px}.inventory-table{width:100%;border-collapse:collapse;font-size:13px}.inventory-table th,.inventory-table td{padding:10px;text-align:left;border-bottom:1px solid #edf2f7;white-space:nowrap}.inventory-table th{position:sticky;top:0;background:#f8fafc;color:#475569}.inventory-table td.path{max-width:440px;overflow:hidden;text-overflow:ellipsis}.inventory-empty{padding:28px;text-align:center;color:#64748b}.inventory-status{min-height:20px;color:#64748b;font-size:13px}.inventory-status.error{color:#b91c1c}.inventory-status.success{color:#047857}html.theme-dark .inventory-drop{background:rgba(30,41,59,.72);border-color:#475569}html.theme-dark .inventory-drop strong{color:#e2e8f0}html.theme-dark .inventory-table-wrap{border-color:#475569}html.theme-dark .inventory-table th{background:#1e293b;color:#cbd5e1}html.theme-dark .inventory-table td{border-color:#334155}@media(max-width:620px){.inventory-toolbar{display:block}.inventory-toolbar label{display:block;max-width:none;margin-bottom:10px}.inventory-table th:nth-child(3),.inventory-table td:nth-child(3){display:none}.inventory-table td.path{max-width:180px}}
            </style>
            <section class="tool-panel">
                <label class="inventory-drop" id="dropZone" for="files"><span><strong>点击选择或拖放文件</strong><small>最多 1,000 个文件，总大小不超过 500 MB；仅收集名称、大小、类型和修改时间</small></span></label>
                <input id="files" type="file" multiple hidden><input id="folder" type="file" webkitdirectory multiple hidden>
                <div class="inventory-buttons"><button class="btn" id="pickFiles" type="button">选择文件</button><button class="btn" id="pickFolder" type="button">选择文件夹</button><button class="btn success" id="exportCsv" type="button" disabled>导出 CSV 清单</button><button class="btn secondary" id="clear" type="button" disabled>清空</button></div>
                <p class="inventory-status" id="status" role="status">文件内容不会被读取或上传服务器。</p>
            </section>
            <section class="tool-panel"><div class="inventory-summary" id="summary"></div><div class="inventory-toolbar"><label for="search">搜索文件名或路径<input id="search" type="search" placeholder="输入关键词筛选" disabled></label><span id="shown">暂未选择文件</span></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>文件名</th><th>类型</th><th>路径</th><th>大小</th><th>修改时间</th></tr></thead><tbody id="rows"><tr><td class="inventory-empty" colspan="5">选择文件后会在这里显示清单。</td></tr></tbody></table></div></section>
            <script>
            (()=>{'use strict';const MAX_FILES=1000,MAX_TOTAL_BYTES=500*1024*1024,$=id=>document.getElementById(id);let files=[];const readable=bytes=>bytes>=1048576?(bytes/1048576).toFixed(2)+' MB':bytes>=1024?(bytes/1024).toFixed(1)+' KB':bytes+' B';function status(message,type=''){const node=$('status');node.textContent=message;node.className='inventory-status '+type;}function extension(file){const name=file.name,last=name.lastIndexOf('.');return last>0?name.slice(last+1).toUpperCase():'无扩展名';}function renderSummary(){const summary=$('summary');summary.replaceChildren();if(!files.length)return;const total=files.reduce((sum,file)=>sum+file.size,0),types=new Set(files.map(extension));[['文件',files.length],['总大小',readable(total)],['文件类型',types.size]].forEach(([label,value])=>{const item=document.createElement('span');item.textContent=label+'：'+value;summary.appendChild(item);});}function render(){const query=$('search').value.trim().toLocaleLowerCase(),visible=files.filter(file=>(file.name+' '+file.path).toLocaleLowerCase().includes(query)),body=$('rows');body.replaceChildren();if(!visible.length){const row=document.createElement('tr'),cell=document.createElement('td');cell.colSpan=5;cell.className='inventory-empty';cell.textContent=files.length?'没有匹配的文件。':'选择文件后会在这里显示清单。';row.appendChild(cell);body.appendChild(row);}else visible.forEach(file=>{const row=document.createElement('tr'),name=document.createElement('td'),type=document.createElement('td'),path=document.createElement('td'),size=document.createElement('td'),time=document.createElement('td');name.textContent=file.name;type.textContent=extension(file);path.className='path';path.title=file.path;path.textContent=file.path||'—';size.textContent=readable(file.size);time.textContent=new Date(file.lastModified).toLocaleString('zh-CN');row.append(name,type,path,size,time);body.appendChild(row);});$('shown').textContent='显示 '+visible.length+' / '+files.length+' 个文件';$('exportCsv').disabled=!files.length;$('clear').disabled=!files.length;$('search').disabled=!files.length;}function setFiles(fileList){const incoming=[...fileList],total=incoming.reduce((sum,file)=>sum+file.size,0);if(!incoming.length)return;if(incoming.length>MAX_FILES||total>MAX_TOTAL_BYTES){status('最多选择 '+MAX_FILES+' 个文件，总大小不能超过 500 MB。','error');return;}files=incoming.map(file=>({name:file.name,size:file.size,lastModified:file.lastModified,path:file.webkitRelativePath||''})).sort((a,b)=>a.path.localeCompare(b.path,'zh-CN')||a.name.localeCompare(b.name,'zh-CN'));$('search').value='';renderSummary();render();status('已生成 '+files.length+' 个文件的本地清单。','success');}function csvField(value){const text=String(value??'');return '"'+(/^[=+\-@]/.test(text)?"'":'')+text.replace(/"/g,'""')+'"';}function exportCsv(){if(!files.length)return;const rows=[['文件名','类型','相对路径','大小（字节）','大小','修改时间'],...files.map(file=>[file.name,extension(file),file.path,file.size,readable(file.size),new Date(file.lastModified).toLocaleString('zh-CN')])],csv='\ufeff'+rows.map(row=>row.map(csvField).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='文件清单-'+new Date().toISOString().slice(0,10)+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('CSV 清单已生成并开始下载。','success');}function clear(){files=[];$('files').value='';$('folder').value='';$('search').value='';renderSummary();render();status('已清空文件清单。','success');}$('files').addEventListener('change',event=>setFiles(event.target.files));$('folder').addEventListener('change',event=>setFiles(event.target.files));$('pickFiles').addEventListener('click',()=>$('files').click());$('pickFolder').addEventListener('click',()=>$('folder').click());$('search').addEventListener('input',render);$('exportCsv').addEventListener('click',exportCsv);$('clear').addEventListener('click',clear);['dragenter','dragover'].forEach(name=>$('dropZone').addEventListener(name,event=>{event.preventDefault();$('dropZone').classList.add('dragging');}));['dragleave','drop'].forEach(name=>$('dropZone').addEventListener(name,event=>{event.preventDefault();$('dropZone').classList.remove('dragging');}));$('dropZone').addEventListener('drop',event=>setFiles(event.dataTransfer.files));render();})();
            </script>
